package candidate

func FirstUnique(values []string) (string, bool) {
	if values == nil {
		return "", false
	}
	counts := make(map[string]int)
	for _, v := range values {
		counts[v]++
	}
	for _, v := range values {
		if counts[v] == 1 {
			return v, true
		}
	}
	return "", false
}

package candidate

import (
	"errors"
	"net/http"
	"strconv"
	"strings"
	"time"
)

// ParseRetryAfter parses an HTTP Retry-After header value.
// It accepts a nonnegative decimal integer representing seconds, or an
// HTTP date in a format accepted by http.ParseTime.
//
// For a valid past date, it returns zero and nil.
// For a valid future date, it returns the exact duration until that date.
//
// It rejects signed integers, negative values, invalid text, and duration overflow.
func ParseRetryAfter(value string, now time.Time) (time.Duration, error) {
	trimmed := strings.TrimSpace(value)
	if trimmed == "" {
		return 0, errors.New("empty Retry-After value")
	}

	// Try parsing as an HTTP date first.
	if t, err := http.ParseTime(trimmed); err == nil {
		delta := t.Sub(now)
		if delta <= 0 {
			return 0, nil
		}
		// Check for overflow: if delta is too large to fit in a time.Duration,
		// return an error.
		if delta > time.MaxDuration {
			return 0, errors.New("Retry-After duration overflow")
		}
		return delta, nil
	}

	// Try parsing as a nonnegative decimal integer.
	// Reject signed integers (e.g., "+5", "-5").
	if len(trimmed) > 0 && (trimmed[0] == '+' || trimmed[0] == '-') {
		return 0, errors.New("signed integer not allowed in Retry-After")
	}

	// Check for any non-digit characters.
	for _, ch := range trimmed {
		if ch < '0' || ch > '9' {
			return 0, errors.New("invalid Retry-After value")
		}
	}

	// Parse as uint64 to avoid overflow issues with strconv.ParseInt.
	secs, err := strconv.ParseUint(trimmed, 10, 64)
	if err != nil {
		return 0, errors.New("invalid Retry-After value")
	}

	// Check for duration overflow: secs * time.Second must fit in time.Duration.
	// time.Duration is int64 on 64-bit systems, max ~9.2e18 seconds.
	// Max uint64 is ~1.8e19, so we need to check.
	const maxDurationSeconds = time.MaxDuration / time.Second
	if secs > maxDurationSeconds {
		return 0, errors.New("Retry-After duration overflow")
	}

	return time.Duration(secs) * time.Second, nil
}
